begin;

-- Head-to-head fixtures are generated by the trusted backend from a
-- round-robin schedule. The authenticated client can only read its league.
create table if not exists public.league_duels (
  id uuid primary key default gen_random_uuid(),
  league_id uuid not null references public.leagues(id) on delete cascade,
  matchday smallint not null check (matchday between 1 and 60),
  player_a uuid not null references auth.users(id) on delete cascade,
  player_b uuid not null references auth.users(id) on delete cascade,
  points_a integer check (points_a is null or points_a >= 0),
  points_b integer check (points_b is null or points_b >= 0),
  bonus_points smallint not null default 3 check (bonus_points between 0 and 10),
  settled_at timestamptz,
  created_at timestamptz not null default now(),
  check (player_a <> player_b),
  check (player_a < player_b),
  check ((points_a is null and points_b is null and settled_at is null)
      or (points_a is not null and points_b is not null and settled_at is not null)),
  unique (league_id, matchday, player_a),
  unique (league_id, matchday, player_b)
);

create index if not exists league_duels_by_player_a
  on public.league_duels (league_id, player_a, matchday);
create index if not exists league_duels_by_player_b
  on public.league_duels (league_id, player_b, matchday);

-- A participant slot prevents a player being scheduled twice in one round,
-- even if they would otherwise appear once as player_a and once as player_b.
create table if not exists public.league_duel_slots (
  league_id uuid not null,
  matchday smallint not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  duel_id uuid not null references public.league_duels(id) on delete cascade,
  primary key (league_id, matchday, user_id),
  unique (duel_id, user_id)
);
alter table public.league_duel_slots enable row level security;
revoke all on public.league_duel_slots from anon, authenticated;
grant all on public.league_duel_slots to service_role;

create or replace function public.validate_league_duel_slot()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (
    select 1
    from public.league_duels d
    where d.id = new.duel_id
      and d.league_id = new.league_id
      and d.matchday = new.matchday
      and new.user_id in (d.player_a, d.player_b)
  ) then
    raise exception 'Duel slot does not match its fixture';
  end if;
  return new;
end;
$$;

drop trigger if exists validate_league_duel_slot
  on public.league_duel_slots;
create trigger validate_league_duel_slot
  before insert or update on public.league_duel_slots
  for each row execute function public.validate_league_duel_slot();

-- Store earned and spent coins as an append-only ledger. Balance is a
-- transactionally maintained cache; only service-role code may award coins.
create table if not exists public.pleno_wallets (
  league_id uuid not null references public.leagues(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  balance integer not null default 0 check (balance >= 0),
  updated_at timestamptz not null default now(),
  primary key (league_id, user_id)
);

create table if not exists public.pleno_wallet_transactions (
  id uuid primary key default gen_random_uuid(),
  league_id uuid not null,
  user_id uuid not null,
  amount integer not null check (amount <> 0),
  reason text not null check (
    reason in ('exact_score', 'sabotage_purchase', 'refund', 'admin_adjustment')
  ),
  idempotency_key uuid not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  foreign key (league_id, user_id)
    references public.pleno_wallets(league_id, user_id) on delete cascade,
  unique (league_id, user_id, idempotency_key)
);

create index if not exists pleno_wallet_transactions_history
  on public.pleno_wallet_transactions (league_id, user_id, created_at desc);

create table if not exists public.sabotage_catalog (
  item_key text primary key,
  name text not null,
  description text not null,
  price integer not null check (price > 0),
  enabled boolean not null default true,
  created_at timestamptz not null default now()
);

insert into public.sabotage_catalog (item_key, name, description, price)
values
  ('screen_glitch', 'Pantalla traviesa', 'Efecto visual breve, aceptado por quien lo recibe y fácil de cerrar.', 20),
  ('clown_frame', 'Marco payaso', 'Marco cosmético temporal; nunca reemplaza el avatar del jugador.', 35)
on conflict (item_key) do nothing;

create table if not exists public.sabotage_inventory (
  league_id uuid not null,
  user_id uuid not null,
  item_key text not null references public.sabotage_catalog(item_key),
  quantity integer not null default 0 check (quantity >= 0),
  updated_at timestamptz not null default now(),
  primary key (league_id, user_id, item_key),
  foreign key (league_id, user_id)
    references public.pleno_wallets(league_id, user_id) on delete cascade
);

-- Pranks are opt-in per league. Consent is off by default and can be
-- withdrawn by the recipient at any time.
create table if not exists public.sabotage_preferences (
  league_id uuid not null references public.leagues(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  accepts_cosmetic_effects boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (league_id, user_id)
);

create table if not exists public.sabotage_events (
  id uuid primary key default gen_random_uuid(),
  league_id uuid not null,
  sender_user_id uuid not null references auth.users(id) on delete cascade,
  target_user_id uuid not null references auth.users(id) on delete cascade,
  item_key text not null references public.sabotage_catalog(item_key),
  status text not null default 'pending'
    check (status in ('pending', 'accepted', 'declined', 'expired', 'cancelled')),
  created_at timestamptz not null default now(),
  responded_at timestamptz,
  effect_expires_at timestamptz,
  check (sender_user_id <> target_user_id),
  foreign key (league_id, sender_user_id)
    references public.pleno_wallets(league_id, user_id) on delete cascade,
  foreign key (league_id, target_user_id)
    references public.pleno_wallets(league_id, user_id) on delete cascade
);

create index if not exists sabotage_events_for_target
  on public.sabotage_events (league_id, target_user_id, created_at desc);

-- Durable outbox for score changes. The worker inserts each official event
-- once; a Supabase Database Webhook can enqueue its push processing.
create table if not exists public.match_event_outbox (
  id uuid primary key default gen_random_uuid(),
  provider_event_key text not null unique,
  match_id bigint not null,
  event_type text not null check (event_type in ('goal', 'match_finished')),
  old_home_goals smallint not null check (old_home_goals >= 0),
  old_away_goals smallint not null check (old_away_goals >= 0),
  new_home_goals smallint not null check (new_home_goals >= 0),
  new_away_goals smallint not null check (new_away_goals >= 0),
  occurred_at timestamptz not null default now(),
  processed_at timestamptz,
  payload jsonb not null default '{}'::jsonb
);
alter table public.match_event_outbox enable row level security;
revoke all on public.match_event_outbox from anon, authenticated;
grant all on public.match_event_outbox to service_role;

alter table public.league_duels enable row level security;
alter table public.pleno_wallets enable row level security;
alter table public.pleno_wallet_transactions enable row level security;
alter table public.sabotage_catalog enable row level security;
alter table public.sabotage_inventory enable row level security;
alter table public.sabotage_preferences enable row level security;
alter table public.sabotage_events enable row level security;

revoke all on public.league_duels, public.league_duel_slots, public.pleno_wallets,
  public.pleno_wallet_transactions, public.sabotage_inventory,
  public.sabotage_preferences, public.sabotage_events,
  public.match_event_outbox
  from anon, authenticated;
grant select on public.league_duels, public.pleno_wallets,
  public.pleno_wallet_transactions, public.sabotage_inventory,
  public.sabotage_preferences, public.sabotage_events
  to authenticated;
grant all on public.league_duels, public.league_duel_slots, public.pleno_wallets,
  public.pleno_wallet_transactions, public.sabotage_inventory,
  public.sabotage_events, public.match_event_outbox to service_role;

grant select on public.sabotage_catalog to authenticated;
grant select, insert, update on public.sabotage_preferences to authenticated;
grant all on public.sabotage_catalog, public.sabotage_preferences to service_role;

drop policy if exists "League members read duels" on public.league_duels;
create policy "League members read duels"
  on public.league_duels for select to authenticated
  using (public.is_league_member(league_id));

drop policy if exists "League members read wallets" on public.pleno_wallets;
create policy "League members read wallets"
  on public.pleno_wallets for select to authenticated
  using (
    user_id = (select auth.uid())
    and public.is_league_member(league_id)
  );

drop policy if exists "League members read wallet transactions"
  on public.pleno_wallet_transactions;
create policy "League members read wallet transactions"
  on public.pleno_wallet_transactions for select to authenticated
  using (
    user_id = (select auth.uid())
    and public.is_league_member(league_id)
  );

drop policy if exists "Players read sabotage catalog" on public.sabotage_catalog;
create policy "Players read sabotage catalog"
  on public.sabotage_catalog for select to authenticated
  using (enabled);

drop policy if exists "League members read inventory" on public.sabotage_inventory;
create policy "League members read inventory"
  on public.sabotage_inventory for select to authenticated
  using (
    user_id = (select auth.uid())
    and public.is_league_member(league_id)
  );

drop policy if exists "Users manage own sabotage preferences"
  on public.sabotage_preferences;
create policy "Users manage own sabotage preferences"
  on public.sabotage_preferences for all to authenticated
  using (
    user_id = (select auth.uid())
    and public.is_league_member(league_id)
  )
  with check (
    user_id = (select auth.uid())
    and public.is_league_member(league_id)
  );

drop policy if exists "League members read sabotage events"
  on public.sabotage_events;
create policy "League members read sabotage events"
  on public.sabotage_events for select to authenticated
  using (
    public.is_league_member(league_id)
    and (
      sender_user_id = (select auth.uid())
      or target_user_id = (select auth.uid())
    )
  );

-- Idempotent exact-score reward. Call only from trusted result-settlement
-- code after a fixture is officially final; never from the browser.
create or replace function public.credit_pleno_coins(
  p_league_id uuid,
  p_user_id uuid,
  p_amount integer,
  p_idempotency_key uuid,
  p_metadata jsonb default '{}'::jsonb
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_balance integer;
  inserted_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Only trusted settlement code may award coins';
  end if;
  if p_amount <= 0 or p_amount > 100 or p_idempotency_key is null then
    raise exception 'Invalid coin award';
  end if;
  if not exists (
    select 1
    from public.league_members lm
    where lm.league_id = p_league_id
      and lm.user_id = p_user_id
  ) then
    raise exception 'Player is not a member of this league';
  end if;

  insert into public.pleno_wallets (league_id, user_id)
  values (p_league_id, p_user_id)
  on conflict do nothing;

  perform 1
  from public.pleno_wallets
  where league_id = p_league_id and user_id = p_user_id
  for update;

  insert into public.pleno_wallet_transactions
    (league_id, user_id, amount, reason, idempotency_key, metadata)
  values
    (p_league_id, p_user_id, p_amount, 'exact_score',
     p_idempotency_key, coalesce(p_metadata, '{}'::jsonb))
  on conflict (league_id, user_id, idempotency_key) do nothing
  returning id into inserted_id;

  if inserted_id is not null then
    update public.pleno_wallets
      set balance = balance + p_amount, updated_at = now()
      where league_id = p_league_id and user_id = p_user_id;
  end if;

  select balance into new_balance
  from public.pleno_wallets
  where league_id = p_league_id and user_id = p_user_id;
  return new_balance;
end;
$$;

revoke all on function public.credit_pleno_coins(uuid, uuid, integer, uuid, jsonb)
  from public, anon, authenticated;
grant execute on function public.credit_pleno_coins(uuid, uuid, integer, uuid, jsonb)
  to service_role;

-- Atomic shop purchase. The client can request a purchase but cannot choose
-- the price, edit balances, or grant inventory directly.
create or replace function public.buy_sabotage_item(
  p_league_id uuid,
  p_item_key text,
  p_request_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  buyer uuid := (select auth.uid());
  item_price integer;
  current_balance integer;
  previous_purchase public.pleno_wallet_transactions%rowtype;
begin
  if buyer is null or not public.is_league_member(p_league_id) then
    raise exception 'League membership required';
  end if;
  if p_request_id is null then
    raise exception 'Request id is required';
  end if;

  select price into item_price
  from public.sabotage_catalog
  where item_key = p_item_key and enabled;
  if item_price is null then
    raise exception 'Item is unavailable';
  end if;

  insert into public.pleno_wallets (league_id, user_id)
  values (p_league_id, buyer)
  on conflict do nothing;

  select balance into current_balance
  from public.pleno_wallets
  where league_id = p_league_id and user_id = buyer
  for update;

  select * into previous_purchase
  from public.pleno_wallet_transactions
  where league_id = p_league_id
    and user_id = buyer
    and idempotency_key = p_request_id
    and reason = 'sabotage_purchase';
  if found then
    if previous_purchase.metadata ->> 'item_key' <> p_item_key then
      raise exception 'Request id was already used for a different item';
    end if;
    return jsonb_build_object(
      'balance', current_balance,
      'item_key', p_item_key,
      'replayed', true
    );
  end if;

  if exists (
    select 1
    from public.pleno_wallet_transactions
    where league_id = p_league_id
      and user_id = buyer
      and idempotency_key = p_request_id
  ) then
    raise exception 'Request id has already been used';
  end if;

  if current_balance < item_price then
    raise exception 'Not enough Pleno Coins';
  end if;

  update public.pleno_wallets
    set balance = balance - item_price, updated_at = now()
    where league_id = p_league_id and user_id = buyer
    returning balance into current_balance;

  insert into public.pleno_wallet_transactions
    (league_id, user_id, amount, reason, idempotency_key, metadata)
  values
    (p_league_id, buyer, -item_price, 'sabotage_purchase', p_request_id,
     jsonb_build_object('item_key', p_item_key));

  insert into public.sabotage_inventory (league_id, user_id, item_key, quantity)
  values (p_league_id, buyer, p_item_key, 1)
  on conflict (league_id, user_id, item_key)
  do update set
    quantity = public.sabotage_inventory.quantity + 1,
    updated_at = now();

  return jsonb_build_object(
    'balance', current_balance,
    'item_key', p_item_key,
    'replayed', false
  );
end;
$$;

revoke all on function public.buy_sabotage_item(uuid, text, uuid)
  from public, anon;
grant execute on function public.buy_sabotage_item(uuid, text, uuid)
  to authenticated;

-- Allow the app to subscribe to changes; row-level policies still decide
-- which rows each authenticated user can see.
do $$
declare
  table_name text;
begin
  if exists (
    select 1 from pg_publication where pubname = 'supabase_realtime'
  ) then
    foreach table_name in array array[
      'league_duels', 'pleno_wallets', 'sabotage_events'
    ] loop
      if not exists (
        select 1
        from pg_publication_tables
        where pubname = 'supabase_realtime'
          and schemaname = 'public'
          and tablename = table_name
      ) then
        execute format(
          'alter publication supabase_realtime add table public.%I',
          table_name
        );
      end if;
    end loop;
  end if;
end $$;

commit;
